import os
from moler.exceptions import CommandFailure  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.sc.perf.db_stats.ue.rtg.kpi_stats import RTGKPIStats
from taf.ul.sc.perf.db_stats.ue.rtg.benchmark_stats import add_benchmark_stats


class RTGStats(object):
    def __init__(self, log_dir, summary_json_file=None):
        self.log_dir = log_dir
        self.unix_local = UnixFunctionality(device_name="UnixLocal", autoconnect=True)
        self.summary_json_file = summary_json_file if summary_json_file else self._get_rtg_report_file_path()

    def add_kpi_stats(self):
        if self.summary_json_file:
            rtg_report = RTGKPIStats(json_file=self.summary_json_file)
            rtg_report.add_throughput_success_rate_stats()
            rtg_report.add_throughput_bitrate_stats()
            rtg_report.add_throughput_packet_rate_stats()
            rtg_report.add_bearers_stats()
            rtg_report.add_rach_stats()
            rtg_report.add_ue_failures_stats()
            rtg_report.add_success_rate_stats()
            rtg_report.add_rrc_reconfiguration_5g_stats()
            rtg_report.add_rrc_reconfiguration_complete_5g_stats()

    def add_benchmark_stats(self):
        add_benchmark_stats(os.path.join(self.log_dir, 'moler'))

    def _get_rtg_report_file_path(self):
        report_file = None
        scenario_name = "*"
        execution_date = "*"
        report_location = os.path.join(self.log_dir, "report", "RTG", scenario_name, execution_date, 'summary.json')
        try:
            ls_output = self.unix_local.ls(options="-tr {} {}".format(report_location, "| tail -1"))
            report_file = list(ls_output['files'].keys())[0]
        except (CommandFailure, KeyError) as error:
            MolerTest.warning(msg="RTG report doesn't exist. Skipping parsing report...")
            MolerTest.warning(msg=error)

        return report_file
